-
-                addr = wmem_new(pinfo->pool, address);
-                addr->type = AT_IPv4;
-                addr->len  = 4;
-                addr->data = addr_data;
+        /* look for the colon before the port, if any */
+        colon_offset = tvb_find_guint8(tvb, end_offset, -1, ':');
+        if (colon_offset == -1) {
+            return;
+        }

-                if (!ws_strtou16(p, NULL, &port)) {
